    "explanation": "Chiến tranh thế giới thứ nhất gây ra thiệt hại nặng nề hơn nhiều so với các cuộc chiến tranh trước đó trong lịch sử vì đây là cuộc chiến tranh đầu tiên có quy mô ứng dụng rộng rãi những thành tựu của cách mạng công nghiệp vào lĩnh vực quân sự, tạo ra các loại vũ khí có sức huỷ diệt vượt trội chưa từng thấy trước đó: súng máy có khả năng bắn liên tục với tốc độ cao, gây thương vong hàng loạt; xe tăng bọc thép có khả năng xuyên phá các phòng tuyến kiên cố; khí độc hoá học gây tổn thương nghiêm trọng, tàn khốc cho binh lính; máy bay quân sự lần đầu tiên được sử dụng rộng rãi trong tác chiến; sự kết hợp của những loại vũ khí công nghiệp hiện đại, có sức sát thương vượt trội này khiến số lượng thương vong trong các trận đánh tăng vọt so với các cuộc chiến tranh sử dụng vũ khí truyền thống trước đó; đồng thời, quy mô của cuộc chiến tranh này cũng vượt xa các cuộc chiến tranh trước đó, khi có sự tham gia huy động lực lượng khổng lồ từ nhiều quốc gia khác nhau trên thế giới, kéo dài trong suốt bốn năm liên tục (1914-1918); chính sự kết hợp giữa vũ khí công nghiệp có sức huỷ diệt lớn và quy mô, thời gian huy động khổng lồ này đã khiến Chiến tranh thế giới thứ nhất gây ra số lượng thương vong về người và thiệt hại về của cải vật chất ở mức độ chưa từng có trong lịch sử loài người tính đến thời điểm đó."
